"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { AppShell } from "../ui/app-shell";
import { getSupabaseBrowserClient } from "../../lib/supabase/client";
import { usePlayerData } from "../../lib/use-player-data";

type Player={id:string;display_name:string|null;email:string};
type Week={id:string;week_number:number;phase:string;focus:string;golf_minutes:number;vector_minutes:number;review_type:string|null};
type Log={id:string;readiness:number|null;state:string|null;safety_status:string;completion_status:string;actual_minutes:number|null;session_rpe:number|null;session_load:number;session_reviews:Array<{decision:string}>};
type Session={id:string;session_blocks:Array<{minutes:number}>;session_logs:Log[]};
type Retest={id:string;retest_type:"baseline"|"no_aid"|"transfer"|"outcome";title:string;protocol:string;success_criterion:string|null;baseline_value:number|null;result_value:number|null;unit:string|null;transfer_passed:boolean|null;player_note:string|null;coach_note:string|null;status:string;scheduled_for:string|null};
type Adjustment={id:string;decision:"keep"|"progress"|"modify"|"stop";rationale:string;evidence_snapshot:Record<string,number>;next_week_focus:string|null;recommended_golf_minutes:number|null;recommended_vector_minutes:number|null;status:string;published_at:string|null};

const blankRetest={retest_type:"no_aid" as Retest["retest_type"],title:"",protocol:"",success_criterion:"",baseline_value:"",unit:"",scheduled_for:""};
const blankResult={result_value:"",unit:"",transfer_passed:"",player_note:""};

export default function ProgressPage(){
  const{profile}=usePlayerData();
  const canCoach=profile?.role==="coach"||profile?.role==="admin";
  const[players,setPlayers]=useState<Player[]>([]),[selectedId,setSelectedId]=useState(""),[weeks,setWeeks]=useState<Week[]>([]),[weekId,setWeekId]=useState(""),[sessions,setSessions]=useState<Session[]>([]),[retests,setRetests]=useState<Retest[]>([]),[adjustments,setAdjustments]=useState<Adjustment[]>([]),[message,setMessage]=useState("");
  const[retest,setRetest]=useState(blankRetest),[resultId,setResultId]=useState(""),[result,setResult]=useState(blankResult),[decision,setDecision]=useState<Adjustment["decision"]>("keep"),[rationale,setRationale]=useState(""),[nextFocus,setNextFocus]=useState(""),[golfMinutes,setGolfMinutes]=useState(0),[vectorMinutes,setVectorMinutes]=useState(0);
  const targetId=canCoach?selectedId:profile?.id||"";

  const loadPlayers=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!canCoach)return;const{data:links}=await sb.from("coach_player_links").select("player_id").eq("coach_id",profile.id);const ids=(links||[]).map(x=>x.player_id);if(!ids.length)return;const{data}=await sb.from("profiles").select("id,display_name,email").in("id",ids);const rows=(data||[])as Player[];setPlayers(rows);setSelectedId(current=>current||rows[0]?.id||"")},[profile,canCoach]);
  const loadWeeks=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!targetId)return;const{data:p}=await sb.from("programmes").select("id").eq("player_id",targetId).in("status",["published","completed"]).order("created_at",{ascending:false}).limit(1).maybeSingle();if(!p){setWeeks([]);return}const{data}=await sb.from("programme_weeks").select("id,week_number,phase,focus,golf_minutes,vector_minutes,review_type").eq("programme_id",p.id).order("week_number");const rows=(data||[])as Week[];setWeeks(rows);setWeekId(current=>current&&rows.some(w=>w.id===current)?current:rows[0]?.id||"")},[targetId]);
  const loadWeek=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!targetId||!weekId)return;const[s,r,a]=await Promise.all([sb.from("programme_sessions").select("id,session_blocks(minutes),session_logs!left(id,readiness,state,safety_status,completion_status,actual_minutes,session_rpe,session_load)").eq("programme_week_id",weekId).eq("session_logs.player_id",targetId),sb.from("programme_retests").select("id,retest_type,title,protocol,success_criterion,baseline_value,result_value,unit,transfer_passed,player_note,coach_note,status,scheduled_for").eq("programme_week_id",weekId).eq("player_id",targetId).order("created_at"),sb.from("week_adjustments").select("id,decision,rationale,evidence_snapshot,next_week_focus,recommended_golf_minutes,recommended_vector_minutes,status,published_at").eq("programme_week_id",weekId).eq("player_id",targetId).order("created_at",{ascending:false})]);if(s.error||r.error||a.error){setMessage(s.error?.message||r.error?.message||a.error?.message||"Could not load weekly review.");return}const sessionRows=(s.data||[])as unknown as Session[],logs=sessionRows.flatMap(item=>item.session_logs||[]),logIds=logs.map(item=>item.id);for(const log of logs)log.session_reviews=[];if(logIds.length){const{data:reviews,error:reviewError}=await sb.from("session_reviews").select("session_log_id,decision").in("session_log_id",logIds);if(reviewError){setMessage(reviewError.message);return}const grouped=new Map<string,Array<{decision:string}>>();for(const review of reviews||[])grouped.set(review.session_log_id,[{decision:review.decision}]);for(const log of logs)log.session_reviews=grouped.get(log.id)||[]}setSessions(sessionRows);setRetests((r.data||[])as Retest[]);setAdjustments((a.data||[])as Adjustment[])},[targetId,weekId]);
  useEffect(()=>{const t=setTimeout(()=>void loadPlayers(),0);return()=>clearTimeout(t)},[loadPlayers]);useEffect(()=>{const t=setTimeout(()=>void loadWeeks(),0);return()=>clearTimeout(t)},[loadWeeks]);useEffect(()=>{const t=setTimeout(()=>void loadWeek(),0);return()=>clearTimeout(t)},[loadWeek]);

  const week=weeks.find(w=>w.id===weekId);
  const evidence=useMemo(()=>{const logs=sessions.flatMap(s=>s.session_logs||[]),planned=sessions.flatMap(s=>s.session_blocks||[]).reduce((n,b)=>n+b.minutes,0),actual=logs.reduce((n,l)=>n+(l.actual_minutes||0),0),completed=logs.filter(l=>l.completion_status==="completed").length,readiness=logs.filter(l=>l.readiness!=null),reviewDecisions=logs.flatMap(l=>l.session_reviews||[]);return{planned,actual,adherence:planned?Math.round(actual/planned*100):0,completed,total:sessions.length,avgReadiness:readiness.length?Number((readiness.reduce((n,l)=>n+(l.readiness||0),0)/readiness.length).toFixed(1)):0,load:logs.reduce((n,l)=>n+(l.session_load||0),0),performing:logs.filter(l=>l.state==="performing").length,fatigued:logs.filter(l=>l.state==="fatigued"||l.state==="declining").length,safetyFlags:logs.filter(l=>l.safety_status!=="clear").length,stopDecisions:reviewDecisions.filter(r=>r.decision==="stop").length}},[sessions]);
  const suggested=useMemo<Adjustment["decision"]>(()=>evidence.safetyFlags>0||evidence.stopDecisions>0?"stop":evidence.adherence<60||evidence.fatigued>=2?"modify":evidence.adherence>=80&&evidence.completed>=2&&evidence.performing>=2?"progress":"keep",[evidence]);
  useEffect(()=>{if(!week)return;const t=setTimeout(()=>{setDecision(suggested);setGolfMinutes(week.golf_minutes);setVectorMinutes(week.vector_minutes)},0);return()=>clearTimeout(t)},[week,suggested]);

  const scheduleRetest=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!week||!targetId)return;const{error}=await sb.from("programme_retests").insert({programme_week_id:week.id,player_id:targetId,created_by:profile.id,...retest,baseline_value:retest.baseline_value===""?null:Number(retest.baseline_value),unit:retest.unit||null,scheduled_for:retest.scheduled_for||null});setMessage(error?error.message:"Retest scheduled for the player.");if(!error){setRetest(blankRetest);await loadWeek()}};
  const submitResult=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!resultId)return;const payload={result_value:result.result_value===""?null:Number(result.result_value),unit:result.unit||null,transfer_passed:result.transfer_passed===""?null:result.transfer_passed==="yes",player_note:result.player_note};const response=canCoach?await sb.from("programme_retests").update({...payload,status:"reviewed",completed_at:new Date().toISOString(),reviewed_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq("id",resultId):await sb.rpc("submit_programme_retest",{target_retest:resultId,submitted_result:payload.result_value,submitted_unit:result.unit,submitted_transfer_passed:payload.transfer_passed,submitted_player_note:result.player_note});setMessage(response.error?response.error.message:"Retest result saved.");if(!response.error){setResultId("");setResult(blankResult);await loadWeek()}};
  const saveAdjustment=async(status:"draft"|"published")=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!week||!targetId)return;const snapshot={...evidence,suggested_decision:suggested,retests_reviewed:retests.filter(r=>r.status==="reviewed").length};const{error}=await sb.from("week_adjustments").insert({programme_week_id:week.id,player_id:targetId,coach_id:profile.id,decision,rationale,evidence_snapshot:snapshot,next_week_focus:nextFocus||null,recommended_golf_minutes:golfMinutes,recommended_vector_minutes:vectorMinutes,status,published_at:status==="published"?new Date().toISOString():null});setMessage(error?error.message:status==="published"?"Weekly decision published to the player.":"Draft weekly decision saved.");if(!error)await loadWeek()};

  const visibleAdjustment=adjustments.find(a=>a.status==="published");
  return <AppShell active="progress"><header className="page-heading"><div><p className="eyebrow">Package 7F.4 · Progression &amp; retesting</p><h1>Review the evidence. Earn the change.</h1><p>Weekly signals support a coaching decision; they do not diagnose a swing cause or alter the programme automatically.</p></div></header>{message&&<div className="success-banner" role="status">{message}</div>}{canCoach&&<section className="progress-player"><label>Review player<select value={selectedId} onChange={e=>setSelectedId(e.target.value)}><option value="">Choose linked player</option>{players.map(p=><option key={p.id} value={p.id}>{p.display_name||p.email}</option>)}</select></label></section>}<nav className="delivery-weeks">{weeks.map(w=><button className={w.id===weekId?"active":""} onClick={()=>setWeekId(w.id)} key={w.id}>Week {w.week_number}<small>{w.phase}</small></button>)}</nav>{week&&<><section className="progress-summary"><div><span>Adherence</span><strong>{evidence.adherence}%</strong><small>{evidence.actual}/{evidence.planned} minutes</small></div><div><span>Sessions</span><strong>{evidence.completed}/{evidence.total}</strong><small>completed</small></div><div><span>Readiness</span><strong>{evidence.avgReadiness||"—"}</strong><small>average / 5</small></div><div><span>Load</span><strong>{evidence.load}</strong><small>session load</small></div><div className={evidence.safetyFlags?"warning":""}><span>Flags</span><strong>{evidence.safetyFlags}</strong><small>safety/monitor</small></div></section><div className="progress-grid"><section className="progress-panel"><p className="eyebrow">Retest register · {week.review_type||"Weekly review"}</p><h2>Test transfer, not just rehearsal.</h2>{retests.map(item=><article className="retest-card" key={item.id}><header><span>{item.retest_type.replace("_"," ")}</span><b>{item.status}</b></header><h3>{item.title}</h3><p>{item.protocol}</p>{item.success_criterion&&<small>Success: {item.success_criterion}</small>}{item.result_value!=null&&<div className="retest-result"><strong>{item.result_value} {item.unit}</strong><span>{item.transfer_passed==null?"Transfer not marked":item.transfer_passed?"Transfer passed":"Transfer not yet passed"}</span>{item.player_note&&<p>{item.player_note}</p>}</div>}{item.status==="scheduled"&&!canCoach&&<button onClick={()=>setResultId(item.id)}>Record result</button>}{canCoach&&item.status==="submitted"&&<button onClick={()=>setResultId(item.id)}>Review result</button>}</article>)}{!retests.length&&<p className="empty-copy">No retest scheduled for this week.</p>}{resultId&&<div className="retest-form"><label>Result<input type="number" step="any" value={result.result_value} onChange={e=>setResult({...result,result_value:e.target.value})}/></label><label>Unit<input value={result.unit} onChange={e=>setResult({...result,unit:e.target.value})} placeholder="%, yards, score…"/></label><label>Transfer outcome<select value={result.transfer_passed} onChange={e=>setResult({...result,transfer_passed:e.target.value})}><option value="">Not assessed</option><option value="yes">Passed</option><option value="no">Not yet passed</option></select></label><label className="wide">Result note<textarea value={result.player_note} onChange={e=>setResult({...result,player_note:e.target.value})}/></label><button className="primary-action" onClick={submitResult}>Save result</button></div>}{canCoach&&<div className="retest-form"><label>Retest type<select value={retest.retest_type} onChange={e=>setRetest({...retest,retest_type:e.target.value as Retest["retest_type"]})}><option value="baseline">Baseline</option><option value="no_aid">No-aid</option><option value="transfer">Transfer</option><option value="outcome">Outcome</option></select></label><label>Title<input value={retest.title} onChange={e=>setRetest({...retest,title:e.target.value})}/></label><label className="wide">Protocol<textarea value={retest.protocol} onChange={e=>setRetest({...retest,protocol:e.target.value})}/></label><label className="wide">Success criterion<input value={retest.success_criterion} onChange={e=>setRetest({...retest,success_criterion:e.target.value})}/></label><label>Date<input type="date" value={retest.scheduled_for} onChange={e=>setRetest({...retest,scheduled_for:e.target.value})}/></label><button className="primary-action" disabled={!retest.title||!retest.protocol} onClick={scheduleRetest}>Schedule retest</button></div>}</section><section className="progress-panel decision-panel"><p className="eyebrow">Next-week decision</p>{canCoach?<><div className={`engine-suggestion ${suggested}`}><span>Evidence-led suggestion</span><strong>{suggested}</strong><small>Coach confirmation required</small></div><div className="decision-reasons"><span>{evidence.performing} performing responses</span><span>{evidence.fatigued} fatigued/declining responses</span><span>{retests.filter(r=>r.status==="reviewed").length} reviewed retests</span></div><label>Coach decision<select value={decision} onChange={e=>setDecision(e.target.value as Adjustment["decision"])}><option value="keep">Keep</option><option value="progress">Progress</option><option value="modify">Modify</option><option value="stop">Stop</option></select></label><label>Evidence and rationale<textarea value={rationale} onChange={e=>setRationale(e.target.value)} placeholder="Explain why the repeated evidence supports this decision."/></label><label>Next-week focus<input value={nextFocus} onChange={e=>setNextFocus(e.target.value)}/></label><div className="minute-fields"><label>Golf minutes<input type="number" min="0" value={golfMinutes} onChange={e=>setGolfMinutes(Number(e.target.value))}/></label><label>Vector minutes<input type="number" min="0" value={vectorMinutes} onChange={e=>setVectorMinutes(Number(e.target.value))}/></label></div><div className="decision-actions"><button onClick={()=>saveAdjustment("draft")} disabled={!rationale}>Save draft</button><button className="primary-action" onClick={()=>saveAdjustment("published")} disabled={!rationale}>Publish decision</button></div></>:visibleAdjustment?<article className={`player-decision ${visibleAdjustment.decision}`}><span>Coach decision</span><h2>{visibleAdjustment.decision}</h2><p>{visibleAdjustment.rationale}</p>{visibleAdjustment.next_week_focus&&<div><small>Next focus</small><strong>{visibleAdjustment.next_week_focus}</strong></div>}<small>{visibleAdjustment.recommended_golf_minutes} golf minutes · {visibleAdjustment.recommended_vector_minutes} Vector minutes</small></article>:<div className="empty-state compact"><h2>Review pending</h2><p>Your coach will publish the next-week decision after reviewing repeated evidence and any scheduled retests.</p></div>}<div className="audit-list"><h3>Decision history</h3>{adjustments.map(a=><div key={a.id}><strong>{a.decision}</strong><span>{a.status}</span><small>{a.rationale}</small></div>)}</div></section></div></>}</AppShell>;
}
